// ============================================================================
// Schedule.hpp  --  v16: arrival rates that change over the day
// ============================================================================
// Arena's Schedule module of Type Arrival: a list of (rate, duration) rows,
// repeated after the last one. A Create that names one produces a Poisson
// stream whose rate follows the rows -- a quiet 7am, a spike at 8, a lull
// after -- which is what the ride-hailing model's rush hour is.
//
// Generated by THINNING (Lewis and Shedler): candidates at the schedule's
// peak rate, each kept with probability rate(t) / peak. It is exact for any
// shape of schedule, including a rate of zero, which the obvious alternative
// -- drawing EXPO(1 / rate(now)) -- is not: a draw made in a quiet hour
// overshoots the busy hour that starts a minute later.
// ============================================================================

#pragma once
#include <string>
#include <vector>
#include "Common.hpp"
#include "Expression.hpp"

namespace des {

enum class TimeUnit { Seconds, Minutes, Hours, Days };

// "Hours" -> TimeUnit::Hours. False for anything else.
bool timeUnitFrom(const std::string& text, TimeUnit& out);
// How many `to` make one `from`: unitsPer(Hours, Minutes) == 60.
double unitsPer(TimeUnit from, TimeUnit to);

// One row, already in the model's base time unit.
struct ScheduleSlot {
    double rate{0.0};       // arrivals per base time unit
    double duration{0.0};   // base time units
};

class ArrivalSchedule {
    std::vector<ScheduleSlot> m_slots;
    double m_cycle{0.0};
    double m_peak{0.0};
public:
    // Throws ModelError for a negative rate or duration, a zero-length cycle,
    // or a schedule whose every rate is zero.
    explicit ArrivalSchedule(std::vector<ScheduleSlot> slots);
    double rateAt(SimTime t) const;          // repeats after the last row
    double peak() const { return m_peak; }
    double cycle() const { return m_cycle; }
    const std::vector<ScheduleSlot>& slots() const { return m_slots; }
    // The first arrival after `now`, by thinning.
    SimTime nextArrival(SimTime now, RandomStream& rng) const;
};

// A Create's interarrival when it follows a schedule. Evaluating it gives the
// gap to the next arrival, so the Create schedules it like any other; its mean
// is unknown on purpose, which is what tells the stability check it cannot
// judge this source rather than letting it assume a rate.
class ScheduledGapExpression : public IExpression {
    std::string     m_scheduleName;
    ArrivalSchedule m_schedule;
    RandomStream*   m_stream{nullptr};
public:
    ScheduledGapExpression(std::string scheduleName, ArrivalSchedule schedule);
    Value evaluate(EvalContext& ctx) const override;
    void validate(const ValidationContext&, std::vector<Diagnostic>&) const override {}
    std::string describe() const override { return "schedule " + m_scheduleName; }
    ExpressionPtr clone() const override;
    void useStream(RandomStream* s) override { m_stream = s; }
    const ArrivalSchedule& schedule() const { return m_schedule; }
};

}  // namespace des
